/** Private real player/window/payload check, with no canonical Storage registration or model binding. */
@EventBusSubscriber(modid="vandorlabs")
public final class StorageEditorClientFixture {
 static final BlockPos ROOT=new BlockPos(0,96,0),PEER=ROOT.east(),ACK=ROOT.east(4);static NativeStorageBlock block;static BlockEntityType<NativeStorageEntity> type;static MenuType<NativeStorageMenu> menu;private static java.util.UUID player;private static int stage;
 public static boolean enabled(){return "storage-editor-client".equals(System.getProperty("vandorlabs.transmitterPhase"));}
 private static void need(boolean yes,String why){if(!yes)throw new IllegalStateException("Storage editor server stage="+stage+": "+why);}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration {
  @SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent event){if(!enabled())return;var id=ResourceLocation.parse("vandorlabs:storage_editor_fixture");event.register(Registries.BLOCK,h->{block=new NativeStorageBlock(BlockBehaviour.Properties.of().strength(5),()->type){@Override protected MenuType<NativeStorageMenu> menuType(){return menu;}};h.register(id,block);});event.register(Registries.ITEM,h->h.register(id,new NativeStorageItem(block,new Item.Properties())));event.register(Registries.BLOCK_ENTITY_TYPE,h->{type=BlockEntityType.Builder.<NativeStorageEntity>of((p,s)->new NativeStorageEntity(type,p,s),block).build(null);h.register(id,type);});event.register(Registries.MENU,h->{menu=net.neoforged.neoforge.common.extensions.IMenuTypeExtension.create((window,inventory,buffer)->new NativeStorageMenu(menu,window,inventory,buffer.readBlockPos()));h.register(id,menu);});}
  @SubscribeEvent public static void packets(net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent event){if(!enabled())return;StorageSettingsPayload.register(event);event.registrar("1").playToServer(Mode.TYPE,new StreamCodec<RegistryFriendlyByteBuf,Mode>(){public Mode decode(RegistryFriendlyByteBuf b){if(b.readableBytes()!=1)throw new IllegalArgumentException("Storage fixture length");return new Mode(b.readUnsignedByte());}public void encode(RegistryFriendlyByteBuf b,Mode mode){b.writeByte(mode.operation);}},(mode,context)->context.enqueueWork(()->{if(context.player() instanceof ServerPlayer actor)apply(actor,mode.operation);}));}
 }
 public record Mode(int operation) implements CustomPacketPayload {static final Type<Mode> TYPE=new Type<>(ResourceLocation.parse("vandorlabs:storage_editor_fixture_mode"));public Mode{if(operation<0||operation>5)throw new IllegalArgumentException("Storage fixture operation");}public Type<? extends CustomPacketPayload> type(){return TYPE;}}
 private static NativeStorageEntity owner(ServerPlayer player,BlockPos pos){return (NativeStorageEntity)player.serverLevel().getBlockEntity(pos);}
 @SubscribeEvent public static void login(PlayerEvent.PlayerLoggedInEvent event){if(!enabled()||!(event.getEntity() instanceof ServerPlayer actor))return;player=actor.getUUID();stage=0;var level=actor.serverLevel();for(int x=-4;x<=10;x++)for(int z=-4;z<=4;z++){level.setBlock(new BlockPos(x,95,z),Blocks.STONE.defaultBlockState(),3);for(int y=96;y<=100;y++)level.setBlock(new BlockPos(x,y,z),Blocks.AIR.defaultBlockState(),3);}for(var pos:new BlockPos[]{ROOT,PEER}){level.setBlock(pos,block.defaultBlockState(),3);var tag=new net.minecraft.nbt.CompoundTag();NativeStorageSettings.fresh().write(tag);owner(actor,pos).loadWithComponents(tag,level.registryAccess());owner(actor,pos).setItem(26,new ItemStack(pos.equals(ROOT)?Items.DIAMOND:Items.GOLD_INGOT,pos.equals(ROOT)?7:3));}actor.setGameMode(GameType.SURVIVAL);actor.getInventory().clearContent();actor.getInventory().selected=0;held(actor,true);actor.connection.teleport(.5,96,-3,0,0);System.out.println("[vandorlabs][storage-editor-client] setup PASS synchronized Survival/slot/tool/position");}
 private static void held(ServerPlayer actor,boolean tool){var stack=tool?new ItemStack(VandorLabsBootstrap.CONFIGURIZER.get()):ItemStack.EMPTY;actor.setItemInHand(InteractionHand.MAIN_HAND,stack);actor.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);actor.connection.send(new net.minecraft.network.protocol.game.ClientboundSetCarriedItemPacket(0));actor.connection.send(new net.minecraft.network.protocol.game.ClientboundContainerSetSlotPacket(-2,0,0,stack.copy()));actor.inventoryMenu.broadcastChanges();}
 private static void unchanged(ServerPlayer actor){var owner=owner(actor,ROOT);var housing=owner.settings().housing();need(housing.mainTexture==295&&housing.layout()==2&&housing.facesEnabled&&housing.faces()[2]==7&&owner.getItem(26).is(Items.DIAMOND)&&owner.getItem(26).getCount()==7,"selected leaf settings and physical slots intact");need(owner(actor,PEER).settings().housing().layout()==0&&owner(actor,PEER).getItem(26).getCount()==3,"peer independent");need(!owner.getUpdateTag(actor.registryAccess()).contains("Items"),"public update has no inventory");}
 private static void apply(ServerPlayer actor,int operation){need(actor.getUUID().equals(player)&&operation==stage,"current actor/order");unchanged(actor);switch(operation){case 0->{need(actor.containerMenu instanceof NativeStorageMenu,"actual dedicated menu");held(actor,false);System.out.println("[vandorlabs][storage-editor-client] roundtrip PASS real widgets/settings42bytes/S2C");}case 1->{need(actor.getMainHandItem().isEmpty(),"tool removed before rejection");System.out.println("[vandorlabs][storage-editor-client] current-tool PASS");}case 2->{need(actor.containerMenu==actor.inventoryMenu,"close processed first");held(actor,true);}case 3->{need(actor.containerMenu==actor.inventoryMenu,"stale window rejected despite restored tool");held(actor,false);System.out.println("[vandorlabs][storage-editor-client] closed-window PASS");}case 4->{need(actor.containerMenu instanceof net.minecraft.world.inventory.ChestMenu&&actor.containerMenu.slots.get(26).getItem().getCount()==7,"ordinary vanilla27 inventory owns physical slots");System.out.println("[vandorlabs][storage-editor-client] inventory PASS");}case 5->{need(actor.containerMenu==actor.inventoryMenu,"inventory closed");System.out.println("[vandorlabs][storage-editor-client] completed PASS");}default->throw new IllegalArgumentException();}actor.serverLevel().setBlock(ACK.east(operation),Blocks.STONE.defaultBlockState(),3);stage++;}
 @SubscribeEvent public static void logout(PlayerEvent.PlayerLoggedOutEvent event){if(!enabled()||!event.getEntity().getUUID().equals(player))return;need(stage==6,"all actual stages complete");System.out.println("[vandorlabs][storage-editor-client] logout PASS");}
}
